// bun tools/schema-gen/cli.ts <config.json> [--check]
//
// Generates a port's input validators from the app's valibot schemas; README.md has the
// config. --check writes nothing and fails if the generated files differ from the ones on
// disk, for CI.
import { spawnSync } from 'node:child_process'
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { join, relative, resolve } from 'node:path'
import { load } from './config'
import { emitRust } from './rust'

const [configPath, flag] = process.argv.slice(2)
if (!configPath) {
  console.error('usage: bun tools/schema-gen/cli.ts <config.json> [--check]')
  process.exit(2)
}
const { config, base, app, files, ir } = await load(configPath)
if (config.ir) writeFileSync(resolve(base, config.ir), `${JSON.stringify(ir, null, 2)}\n`)

function revision(dir: string) {
  const result = spawnSync('git', ['-C', dir, 'rev-parse', '--short', 'HEAD'], { encoding: 'utf8' })
  return result.status === 0 ? result.stdout.trim() : 'unknown'
}
const kit = resolve(import.meta.dir, '../..')
const header = [
  'Generated by the porting kit\'s schema generator; do not edit.',
  `From ${config.app} at ${revision(app)}: ${files.join(', ')}`,
  `Kit ${revision(kit)}; command: bun <kit>/tools/schema-gen/cli.ts ${relative(process.cwd(), resolve(configPath))}`,
]
const { files: emitted, hooks } = emitRust(ir, { ...config.rust, header })
const copied = ['runtime.rs', ...(config.rust.revive?.dates ? ['js_date.rs'] : [])]
for (const name of copied) {
  emitted[name] = `${header.map((l) => `// ${l}`).join('\n')}\n${readFileSync(join(import.meta.dir, name), 'utf8')}`
}

const out = resolve(base, config.rust.out)
const stale: string[] = []
mkdirSync(out, { recursive: true })
const scratch = join(out, '.schema-gen')
mkdirSync(scratch, { recursive: true })
for (const [name, text] of Object.entries(emitted)) {
  const path = join(scratch, name)
  writeFileSync(path, text)
  spawnSync('rustfmt', ['--edition', '2024', path])
  const formatted = readFileSync(path, 'utf8')
  const target = join(out, name)
  if (flag === '--check') {
    if (!existsSync(target) || readFileSync(target, 'utf8') !== formatted) stale.push(name)
  } else {
    writeFileSync(target, formatted)
  }
}
spawnSync('rm', ['-r', scratch])

if (flag === '--check') {
  if (stale.length) {
    console.error(`Out of date: ${stale.join(', ')}. Run without --check.`)
    process.exit(1)
  }
  console.log('Generated files are up to date.')
} else {
  console.log(`${ir.inputs.length} inputs, ${Object.keys(ir.nodes).length} nodes, ${hooks.length} hooks -> ${relative(process.cwd(), out)}`)
}
